import { useMemo, useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date;
  defaultValue?: Date;
  onChange?: (date: Date) => void;
};

const startOfDay = (date: Date) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const addDays = (date: Date, amount: number) => {
  const result = startOfDay(date);
  result.setDate(result.getDate() + amount);
  return result;
};

const isSameDay = (a: Date, b: Date) => startOfDay(a).getTime() === startOfDay(b).getTime();

export default function ReportDatePicker({
  value,
  defaultValue,
  onChange,
}: ReportDatePickerProps) {
  const [internalValue, setInternalValue] = useState<Date>(() =>
    startOfDay(defaultValue ?? new Date()),
  );

  const selected = value ? startOfDay(value) : internalValue;

  const presets = useMemo(() => {
    const today = startOfDay(new Date());
    return [
      { id: 'today', label: 'Сегодня', date: today },
      { id: 'yesterday', label: 'Вчера', date: addDays(today, -1) },
      { id: 'week-ago', label: 'Неделя назад', date: addDays(today, -7) },
    ];
  }, []);

  const select = (next: Date) => {
    const day = startOfDay(next);
    if (value === undefined) {
      setInternalValue(day);
    }
    onChange?.(day);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-3)',
      }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2)' }}
      >
        {presets.map((preset) => {
          const active = isSameDay(selected, preset.date);
          return (
            <JxButton
              key={preset.id}
              size="sm"
              variant={active ? 'primary' : 'secondary'}
              aria-pressed={active}
              onClick={() => select(preset.date)}
            >
              {preset.label}
            </JxButton>
          );
        })}
      </div>

      <JxCalendar
        aria-label="Дата отчёта"
        value={selected}
        onValueChange={(next: Date | null) => {
          if (next) {
            select(next);
          }
        }}
      />
    </div>
  );
}

